    HfField field=HF_FIELD(WeaponMagazine,capacity);HfValue desired=HF_U32(20);HfLiveValue v={0};
    const uint64_t target=UINT64_C(0xAA69A60D74A3EC54);const char* owner="superearth.arsenal-native-port";
